{"filename": "test_parse_csv.py", "content": "import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
parse_csv_line = target.parse_csv_line


def test_basic_csv_split():
    """Basic comma-separated values are split into a list."""
    assert parse_csv_line("a,b,c") == ["a", "b", "c"]


def test_whitespace_stripped():
    """Surrounding whitespace around every field is stripped."""
    assert parse_csv_line(" a , b , c ") == ["a", "b", "c"]


def test_empty_fields_preserved():
    """Empty fields are preserved."""
    assert parse_csv_line("a,,c") == ["a", "", "c"]


def test_no_quoted_csv():
    """Parser intentionally does not implement quoted CSV; comma inside quotes is still a delimiter."""
    assert parse_csv_line('"hello, world",b') == ['"hello', 'world"', 'b']


def test_single_field():
    """A line with no commas returns a single-field list."""
    assert parse_csv_line("hello") == ["hello"]


def test_non_string_raises_typeerror():
    """Non-string input raises TypeError."""
    try:
        parse_csv_line(123)
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_multiple_spaces_stripped():
    """Multiple spaces around fields are all stripped."""
    assert parse_csv_line("  a  ,  b  ") == ["a", "b"]


def test_tab_and_newline_stripped():
    """Surrounding whitespace (including tabs) is stripped."""
    assert parse_csv_line(" a \t, b ") == ["a", "b"]
"}

